import typing

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N <= 0:
        return 0

    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # We move from (1,1) to (N,N); each step increases x or y by 1.
    # Step s = x + y, so initial s = 1+1 = 2, final s = N+N = 2N.
    # We use a DP where dimension is steps and positions on both paths at that step.
    # To save memory, we can do layer-by-layer over s.

    NEG_INF = -10**9
    # dp[x1][y1][x2][y2] is too large. Instead, at step s, x1+y1=s, x2+y2=s.
    # So x1 in [max(1, s-N), min(N, s-1)], similarly for x2.
    # We'll store as a 2D array: dp[x1][x2] for current step, where y1=s-x1, y2=s-x2.

    # Initialize: step s=2, x1=1, y1=1; x2=1, y2=1 -> only one state
    dp = {}
    dp[(1, 1)] = grid[1][1]  # both on same cell, count once

    for s in range(3, 2 * N + 1):
        new_dp = {}
        # x1 ranges such that y1 = s - x1 is in [1, N]
        x1_min = max(1, s - N)
        x1_max = min(N, s - 1)
        for x1 in range(x1_min, x1_max + 1):
            y1 = s - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(x1_min, x1_max + 1):
                y2 = s - x2
                if y2 < 1 or y2 > N:
                    continue
                # transition from previous step s-1:
                # previous x1' could be x1 (came from left: y1-1) or x1-1 (came from top)
                # similarly for x2
                best = NEG_INF
                for dx1 in (0, -1):  # dx1=0 means came from same x (left), dx1=-1 means came from x1-1 (top)
                    prev_x1 = x1 + dx1
                    if prev_x1 < 1 or prev_x1 > N:
                        continue
                    prev_y1 = (s - 1) - prev_x1
                    if prev_y1 < 1 or prev_y1 > N:
                        continue
                    for dx2 in (0, -1):
                        prev_x2 = x2 + dx2
                        if prev_x2 < 1 or prev_x2 > N:
                            continue
                        prev_y2 = (s - 1) - prev_x2
                        if prev_y2 < 1 or prev_y2 > N:
                            continue
                        key = (prev_x1, prev_x2)
                        if key in dp:
                            val = dp[key]
                            cell_val = grid[x1][y1]
                            if x1 == x2 and y1 == y2:
                                cell_val2 = 0
                            else:
                                cell_val2 = grid[x2][y2]
                            total = val + cell_val + cell_val2
                            if total > best:
                                best = total
                if best > NEG_INF:
                    new_dp[(x1, x2)] = best
        dp = new_dp

    # At final step s=2N, x1+y1=2N. Since x1<=N, y1<=N, must have x1=N, y1=N.
    # So only state is (N, N)
    return dp.get((N, N), 0)

