from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not coeffs:
        return "0"

    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        degree = n - i

        # Determine sign
        if coeff > 0:
            if terms:
                sign = "+"
            else:
                sign = ""
            abs_coeff = coeff
        else:
            if terms:
                sign = "-"
            else:
                sign = "-"
            abs_coeff = -coeff

        # Determine coefficient part
        if degree > 0 and abs_coeff == 1:
            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return "0"

    return "".join(terms)
