def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their GCD
    and y0 as their LCM.
    """
    # Handle edge cases: if y0 is not divisible by x0, no such pairs exist
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0  # quotient such that a * b = n and gcd(a, b) = 1

    import math

    count = 0
    # Iterate through all divisors a of n
    for a in range(1, int(math.isqrt(n)) + 1):
        if n % a == 0:
            b = n // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count
