def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    # Helper function to parse a statement and return the truth value given the scenario
    def parse_statement(statement: str) -> bool:
        statement = statement.strip()
        if not statement:
            return True  # Empty statement is trivially true

        # Check if the statement is about a day of the week - ignore such statements
        if statement in days_of_week:
            return True  # Disregard day of week statements

        # Parse "I am guilty" or "I am not guilty"
        if statement == "I am guilty":
            return True  # In this scenario, speaker IS guilty (we are testing this scenario)
        elif statement == "I am not guilty":
            return False  # In this scenario, speaker IS guilty, so "I am not guilty" is false

        # Parse "<NAME> is guilty" or "<NAME> is not guilty"
        guilty_keyword = "is guilty"
        not_guilty_keyword = "is not guilty"

        if " is not guilty" in statement:
            # Extract the name
            name_part = statement.replace("is not guilty", "").strip()
            is_true = (name_part != scenario)
            return is_true
        elif " is guilty" in statement:
            # Extract the name
            name_part = statement.replace("is guilty", "").strip()
            is_true = (name_part == scenario)
            return is_true
        else:
            # For any other statement, treat it as true (or we could return True to be safe)
            # Since the problem says we disregard day of week statements, and other statements
            # are likely about guilt, if we can't parse it, return True to not break consistency
            return True

    # For each participant, check consistency
    for participant, speaker_statements in statements.items():
        is_liar = participant in liar_count

        for statement in speaker_statements:
            truth_value = parse_statement(statement)
            # If participant is a liar, their statement should be false
            # If participant is not a liar, their statement should be true
            if is_liar:
                if truth_value:
                    return False
            else:
                if not truth_value:
                    return False

    return True
