def calculate_score(system: int, points: str) -> list:
    if system not in (11, 21):
        raise ValueError("system must be 11 or 21")

    game_scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1
        else:
            raise ValueError("points string must contain only 'W' and 'L'")

        player_wins = (player_score >= system) and (player_score - opponent_score >= 2)
        opponent_wins = (opponent_score >= system) and (opponent_score - player_score >= 2)

        if player_wins or opponent_wins:
            game_scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        game_scores.append(f"{player_score}:{opponent_score}")

    return game_scores

