from typing import List, Tuple

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Handle edge case where there are no herbs or no time
    if T <= 0 or M <= 0 or not herbs:
        return 0

    # dp[t] will store the maximum value achievable with time t
    dp = [0] * (T + 1)

    for i in range(M):
        # herbs[i] is a tuple (time, value)
        if i >= len(herbs):
            break
        time_needed, value = herbs[i]
        if time_needed > T:
            continue
        # Iterate backwards to avoid using the same herb multiple times
        for t in range(T, time_needed - 1, -1):
            if dp[t] < dp[t - time_needed] + value:
                dp[t] = dp[t - time_needed] + value

    return dp[T]
