def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if n == 0:
        return V
    if V == 0:
        return 0

    dp = [0] * (V + 1)

    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            new_value = dp[j - vol] + vol
            if new_value > dp[j]:
                dp[j] = new_value

    max_occupied = dp[V]
    return V - max_occupied
