def minimum_students_to_leave(heights):
    if not heights:
        return 0
    n = len(heights)
    if n == 1:
        return 0

    # Compute longest increasing subsequence ending at each index
    inc = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute longest decreasing subsequence starting at each index
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The longest choir formation is the maximum length of inc[i] + dec[i] - 1
    longest_choir = 0
    for i in range(n):
        longest_choir = max(longest_choir, inc[i] + dec[i] - 1)

    return n - longest_choir

