def hanoi_double_iterative(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return 0
    if n == 1:
        return 2

    moves = 2
    for i in range(2, n + 1):
        moves = 2 * moves + 2
    return moves

def total_smoked_cigarettes(n, k):
    if n < 0:
        raise ValueError("n must be non-negative")
    if k <= 1:
        raise ValueError("k must be greater than 1")
    total = n
    butts = n
    while butts >= k:
        new_cigs = butts // k
        total += new_cigs
        # Butts from exchanged whole cigarettes plus leftover butts
        butts = new_cigs + (butts % k)
    return total
